import pandas as pd

def clean(df):
    df = df.copy()
    df = df.drop_duplicates()
    if 'Region' in df.columns:
        df['Region'] = df['Region'].replace({'Nort': 'North'})
    if 'Quantity' in df.columns:
        df['Quantity'] = pd.to_numeric(df['Quantity'], errors='coerce').abs()
    if {'Quantity', 'Price', 'Revenue'}.issubset(df.columns):
        df['Revenue'] = df['Quantity'] * df['Price']
    return df

def answer(df):
    df = clean(df)
    grouped = df.groupby('Region', dropna=True)['Quantity'].sum()
    result = {}
    for key, value in grouped.items():
        value = float(value)
        result[str(key)] = int(value) if value.is_integer() else value
    return result
